import type { CardioSession, Equipment, Goal, PlanDay, Prescription } from './types';

export type Tri = [string, string, string];
export type Place = 'gym' | 'home' | 'bodyweight' | 'outdoor';
export type RoutineTag = 'strength' | 'hypertrophy' | 'running' | 'cycling' | 'hiit' | 'mobility' | 'hybrid' | 'calisthenics' | 'health';
export type RItem = [id: string, sets: number, reps: string, restSec?: number];
export interface RDay { n: Tri; kind: 'strength' | 'cardio' | 'hiit' | 'mobility'; items?: RItem[]; cardio?: CardioSession; note?: Tri }
export interface Routine {
  id: string; n: Tri; d: Tri; goal: Goal; level: 1 | 2 | 3; place: Place; equipment: Equipment[]; tags: RoutineTag[];
  /** sessions per week when repeated; for multi-week programs, per week */
  perWeek: number; weeks: number;
  /** a single week template, or explicit weeks (programs such as couch-to-5K) */
  program: RDay[][];
}

const T = (es: string, en: string, pt: string): Tri => [es, en, pt];
const S = (n: Tri, items: RItem[], kind: RDay['kind'] = 'strength'): RDay => ({ n, kind, items });
const C = (n: Tri, cardio: CardioSession, note?: Tri): RDay => ({ n, kind: 'cardio', cardio, note });

