const wr = (a: string) => T(a, a, a);
/** Run/walk progression in the style of the popular "couch to 5K" plans (own wording; not an official program). */
function couchTo5k(): RDay[][] {
  const w: RDay[][] = [];
  for (let i = 0; i < 4; i++) {
    const [d1] = C25K_NOTES[i]!;
    const iv = [{ reps: 8, workSec: 60, restSec: 90 }, { reps: 6, workSec: 90, restSec: 120 }, { reps: 4, workSec: 135, restSec: 135 }, { reps: 3, workSec: 240, restSec: 120 }][i]!;
    w.push([0, 1, 2].map((k) => C(T(`Día ${k + 1}`, `Day ${k + 1}`, `Dia ${k + 1}`), run('walkrun', 25 + i * 2, iv), d1)));
  }
  const w5 = [[T('5 trote · 3 caminata · 5 trote · 3 caminata · 5 trote', '5 jog · 3 walk · 5 jog · 3 walk · 5 jog', '5 trote · 3 caminhada · 5 trote · 3 caminhada · 5 trote'), 30], [T('8 trote · 5 caminata · 8 trote', '8 jog · 5 walk · 8 jog', '8 trote · 5 caminhada · 8 trote'), 30], [T('20 min trote continuo', '20 min continuous jog', '20 min de trote contínuo'), 28]] as const;
  w.push(w5.map(([note, m], k) => C(T(`Día ${k + 1}`, `Day ${k + 1}`, `Dia ${k + 1}`), run(k === 2 ? 'zone2' : 'walkrun', m, k === 2 ? undefined : { reps: 3, workSec: 480, restSec: 240 }), note as Tri)));
  w.push([[T('5 · 3 · 8 · 3 · 5 (trote/caminata)', '5 · 3 · 8 · 3 · 5 (jog/walk)', '5 · 3 · 8 · 3 · 5 (trote/caminhada)'), 32], [T('10 trote · 3 caminata · 10 trote', '10 jog · 3 walk · 10 jog', '10 trote · 3 caminhada · 10 trote'), 33], [T('25 min trote continuo', '25 min continuous jog', '25 min de trote contínuo'), 28]].map(([note, m], k) => C(T(`Día ${k + 1}`, `Day ${k + 1}`, `Dia ${k + 1}`), run(k === 2 ? 'zone2' : 'walkrun', m as number), note as Tri)));
  for (const m of [25, 28, 30]) w.push([0, 1, 2].map((k) => C(T(`Día ${k + 1}`, `Day ${k + 1}`, `Dia ${k + 1}`), run('zone2', m), wr(`${m} min`))));
  return w;
}

function runBlock(weeks: number, perWeek: 3 | 4, base: number, longStart: number, longStep: number, vo2: boolean): RDay[][] {
  return Array.from({ length: weeks }, (_, w) => {
    const deload = (w + 1) % 4 === 0;
    const f = deload ? 0.7 : 1;
    const days: RDay[] = [
      C(EASY, run('zone2', Math.round((base + w * 2) * f))),
      C(vo2 ? INT : TEMPO, vo2 ? run('intervals', Math.round((35 + w) * f), { reps: Math.min(6, 4 + Math.floor(w / 3)), workSec: 180, restSec: 120 }) : run('tempo', Math.round((30 + w * 1.5) * f))),
      C(LONG, run('long', Math.round((longStart + w * longStep) * f))),
    ];
    if (perWeek === 4) days.splice(2, 0, C(EASY, run('zone2', Math.round((base + 5) * f))));
    return days;
  });
}
function bikeBlock(weeks: number, vo2: boolean): RDay[][] {
  return Array.from({ length: weeks }, (_, w) => {
    const deload = (w + 1) % 4 === 0, f = deload ? 0.7 : 1;
    return [
      C(T('Rodaje base', 'Base ride', 'Pedal de base'), bike('zone2', Math.round((50 + w * 4) * f))),
      C(vo2 ? T('4 × 4 min (VO₂máx)', '4 × 4 min (VO₂max)', '4 × 4 min (VO₂máx)') : T('Tempo / sweet spot', 'Tempo / sweet spot', 'Tempo / sweet spot'), vo2 ? bike('intervals', 55, { reps: 4, workSec: 240, restSec: 180 }) : bike('tempo', Math.round((50 + w * 3) * f))),
      C(T('Salida larga', 'Long ride', 'Pedal longo'), bike('long', Math.round((90 + w * 8) * f))),
    ];
  });
}

