export const routineById = (id: string) => ROUTINES.find((r) => r.id === id);

const parseReps = (r: string): [number, number] => { const [a, b] = r.split('-').map(Number); return [a ?? 8, b ?? a ?? 12]; };
export function routineWeekDays(r: Routine, weekIndex: number): PlanDay[] {
  const week = r.program[Math.min(Math.max(0, weekIndex), r.program.length - 1)]!;
  return week.map((d, i) => {
    const items: Prescription[] = (d.items ?? []).map(([exerciseId, sets, reps, restSec]) => {
      const [repMin, repMax] = parseReps(reps);
      return { exerciseId, sets, repMin, repMax, rirTarget: d.kind === 'strength' ? 2 : 4, load: 0, restSec };
    });
    return { name: `D${i + 1}`, kind: d.kind, items, cardio: d.cardio };
  });
}
